llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Erythromycin, the closest structural analogue sharing the full macrolide core and sugar residues, has absolute oral bioavailability of 32 ± 7% in healthy subjects, which is above the 20% threshold; the query's 9-oxime ether modification is acid-stabilizing and expected to improve on this value.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Clarithromycin, a closely related 6-O-methyl erythromycin derivative, has absolute oral bioavailability of 55% at 250 mg in humans, demonstrating that relatively minor modifications of the erythromycin scaffold can raise F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Erythromycin estolate, an acid-stable ester prodrug of erythromycin, achieves 70-80% oral bioavailability, showing that protecting the macrolide from gastric degradation markedly increases absorption; the query's oxime ether serves a similar protective role.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Telithromycin, a semi-synthetic macrolide with the same desosamine sugar and large macrocycle, has absolute oral bioavailability of 56.6% in elderly volunteers, supporting high F for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Solithromycin, a fluorinated macrolide, has absolute oral bioavailability of 62% (46-80%) at 400 mg, further supporting that macrolide derivatives can exceed 20% F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Dirithromycin, a macrolide with a 9,11-cyclic carbamate prodrug structure, has systemic availability of only 6-14%; however, its distinct prodrug conversion and metabolic profile make this low-F result poorly transferable to the query's oxime ether.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is roxithromycin, an erythromycin 9-oxime ether designed for acid stability. Direct macrolide evidence—erythromycin (32%), clarithromycin (55%), estolate (70-80%), telithromycin (57%), and solithromycin (62%)—strongly supports F ≥ 20%; the low-F dirithromycin result is structurally distinct and poorly transferable. Therefore predict high.",
  "evidence_gaps": [
    "No direct roxithromycin absolute bioavailability record is present in the provided evidence set; prediction relies on close macrolide analogues and the known acid-stabilizing effect of the oxime ether.",
    "The physicochemical prior flags high molecular weight, TPSA, and ionization, but this is overridden by experimental macrolide bioavailability data; direct permeability or transport data for the query would reduce residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

